/**
 * Chunks an async iterable stream into fixed-size batches.
 */
async function* batchAsyncStream(asyncIterable, batchSize = 3) {
  let batch = [];
  for await (const item of asyncIterable) {
    batch.push(item);
    if (batch.length >= batchSize) {
      yield batch;
      batch = [];
    }
  }
  if (batch.length > 0) {
    yield batch;
  }
}
